import '../../domain/entities/exam_entity.dart'; class ExamModel extends ExamEntity { const ExamModel({required super.id,required super.name,required super.type,required super.academicSession,required super.classId,required super.sectionId,required super.subject,required super.examDate,required super.totalMarks,required super.passingMarks,required super.createdAt}); factory ExamModel.fromMap(Map<String,dynamic> map)=>ExamModel(id:map['id']??'',name:map['name']??'',type:ExamType.values.firstWhere((v)=>v.name==map['type'],orElse:()=>ExamType.monthly),academicSession:map['academicSession']??'',classId:map['classId']??'',sectionId:map['sectionId']??'',subject:map['subject']??'',examDate:DateTime.parse(map['examDate']),totalMarks:(map['totalMarks'] as num).toDouble(),passingMarks:(map['passingMarks'] as num).toDouble(),createdAt:DateTime.parse(map['createdAt'])); factory ExamModel.fromEntity(ExamEntity e)=>ExamModel(id:e.id,name:e.name,type:e.type,academicSession:e.academicSession,classId:e.classId,sectionId:e.sectionId,subject:e.subject,examDate:e.examDate,totalMarks:e.totalMarks,passingMarks:e.passingMarks,createdAt:e.createdAt); Map<String,dynamic> toMap()=>{'id':id,'name':name,'type':type.name,'academicSession':academicSession,'classId':classId,'sectionId':sectionId,'subject':subject,'examDate':examDate.toIso8601String(),'totalMarks':totalMarks,'passingMarks':passingMarks,'createdAt':createdAt.toIso8601String()}; }
